window.docContents[212].resolve({"/Tactic-Proofs/Custom-Tactics/#custom-tactics":{"contents":"\n\nTactics are productions in the syntax category tactic. \nGiven the syntax of a tactic, the tactic interpreter is responsible for carrying out actions in the tactic monad TacticM, which is a wrapper around Lean's term elaborator that keeps track of the additional state needed to execute tactics.\nA custom tactic consists of an extension to the tactic category along with either:\n\n* a macro that translates the new syntax into existing syntax, or* an elaborator that carries out TacticM actions to implement the tactic.\n\n\n\n","context":"Lean 中文参考手册\u0009Tactic Proofs","header":"14.8. Custom Tactics","id":"/Tactic-Proofs/Custom-Tactics/#custom-tactics"}});